insert into public.workout_plans(id,payload) values('beginner-none','{"equipment":"none","week":[{"name":"Rest & reset","strength":false,"minutes":0,"exercises":[],"description":"Rest, or take a gentle stroll if you feel like it.","caution":""},{"name":"Full-body foundations","strength":true,"minutes":20,"exercises":[{"name":"Chair squat","reps":8,"sets":2,"instructions":"Sit back toward a stable chair. Keep knees comfortable, press through your feet and stand slowly. Use light loads at the gym.","easier":"Use a higher chair or hold a stable support."},{"name":"Wall push-up","reps":8,"sets":2,"instructions":"Keep your body aligned. Bend your elbows slowly, then press away. Breathe throughout.","easier":"Stand closer to the wall."},{"name":"Hip hinge","reps":10,"sets":2,"instructions":"With a soft knee bend, push hips back while keeping your back comfortable. Stand tall slowly.","easier":"Practise a short range of motion holding a support."},{"name":"Supported calf raise","reps":12,"sets":2,"instructions":"Hold a stable surface. Lift heels slowly, pause, and lower with control.","easier":"Try seated calf raises."}],"description":"Warm up gently for 3–5 minutes. Rest 60–90 seconds between sets. Finish feeling you could do a little more.","caution":""},{"name":"Comfortable walk","strength":false,"minutes":15,"exercises":[],"description":"Walk at a pace where you can hold a conversation. Split the time into shorter walks if needed.","caution":""},{"name":"Full-body foundations","strength":true,"minutes":20,"exercises":[{"name":"Chair squat","reps":8,"sets":2,"instructions":"Sit back toward a stable chair. Keep knees comfortable, press through your feet and stand slowly. Use light loads at the gym.","easier":"Use a higher chair or hold a stable support."},{"name":"Wall push-up","reps":8,"sets":2,"instructions":"Keep your body aligned. Bend your elbows slowly, then press away. Breathe throughout.","easier":"Stand closer to the wall."},{"name":"Hip hinge","reps":10,"sets":